"""Campaign compiler, typed replay, filtering, and state preparation.

Layouts, declaration order, and composed filter applications are compiled once
per entry, never per witness.  The replay loop then decodes each recorded
KTEST strictly, so a transport, inventory, or leaf failure marks only that run
INVALID_TEST; the pipe flag is validated as an attestation before any filtering
verdict; filtering precedes reachability, which precedes deduplication; and
corpus indices follow first usable run order.
"""

from typing import Any, Dict, List, Optional, Tuple

from eywa.ast import parse_expr, parse_module, parse_types
from eywa.composer import DependencyGraph
from eywa.oracles import ResultReader, TestError, TypeCollector, build_layout
from eywa.run import Corpus, identity
from eywa.state import Machine, Preparation
from eywa.wire import decode

INVALID = {"status": "INVALID_TEST"}
FILTERED = {"status": "FILTERED"}
UNREACHABLE = {"status": "UNREACHABLE"}


class Plan(object):
    """Everything the replay loop needs about one entry."""

    __slots__ = ("entry", "certificate", "layout", "reader", "predicate",
                 "applications", "names", "preparation", "machine")

    def __init__(self, entry, certificate, layout, predicate, applications,
                 preparation):
        self.entry = entry
        self.certificate = certificate
        self.layout = layout
        self.reader = ResultReader(layout)
        self.predicate = predicate
        self.applications = applications
        self.names = layout.param_names
        self.preparation = preparation


def compile_plan(entry, module, types, graph, machine) -> Plan:
    """Compile one entry plan: module order, declarations, slots, filters."""
    order = graph.compile_order(entry)
    declarations: List[str] = []
    seen = set()
    for name in order:
        model = graph.models.get(name)
        if model is None:
            continue
        for parameter in model.inputs:
            TypeCollector.collect(parameter.type, declarations, seen)
        TypeCollector.collect(model.result.type, declarations, seen)

    has_pipes = graph.has_direct_pipe(entry)
    layout = build_layout(module, has_pipes)
    certificate = {
        "entry": entry,
        "modules": order,
        "types": declarations,
        "slots": [[name, list(path), width] for name, path, width in layout.slots],
        "flag": ("x%d" % layout.flag_root) if has_pipes else None,
        "variables": layout.variables,
    }

    applications: List[Tuple[Optional[Any], Tuple[Tuple[str, str], ...]]] = []
    for filter_name, binding in graph.applications(entry):
        model = graph.models.get(filter_name)
        guard = None if model is None else model.precondition
        applications.append((guard, tuple(binding.items())))

    preparation = None
    if machine is not None:
        context = {p.name: p.type for p in module.inputs}
        preparation = Preparation(
            machine, lambda source: parse_expr(source, types, context), {})

    return Plan(entry, certificate, layout, module.precondition, applications,
                preparation)


def execute(campaign) -> Dict[str, Any]:
    """Compile a campaign and emit its complete certificate."""
    if not isinstance(campaign, dict):
        raise TestError("campaign is not an object")
    types = parse_types(campaign.get("types") or [])
    models = {}
    for spec in campaign.get("modules") or []:
        models[spec["name"]] = parse_module(spec, types)

    graph = DependencyGraph(models)
    for name in models:
        graph.Node(name)
    for caller, callee in campaign.get("calls") or []:
        graph.CallEdge(caller, [callee])
    for pipe in campaign.get("pipes") or []:
        graph.Pipe(pipe["target"], pipe["filter"], pipe.get("bind") or {})

    spec = campaign.get("machine")
    machine = None if spec is None else Machine(spec)

    plans: Dict[str, Plan] = {}
    plans_certificate: List[Dict[str, Any]] = []
    for entry in campaign.get("entries") or []:
        plan = compile_plan(entry, models[entry], types, graph, machine)
        plans[entry] = plan
        plans_certificate.append(plan.certificate)

    records: List[Dict[str, Any]] = []
    corpus = Corpus()
    for position, run in enumerate(campaign.get("runs") or []):
        records.append(replay(run, position, plans, machine, corpus))
    return {"plans": plans_certificate, "records": records,
            "corpus": corpus.certificate()}


def replay(run, position, plans, machine, corpus) -> Dict[str, Any]:
    """Recover, attest, filter, prepare, and deduplicate one witness."""
    plan = plans.get(run["entry"])
    if plan is None:
        return dict(INVALID)
    layout = plan.layout
    try:
        objects = decode(run["ktest"], layout.widths)
        values, keys, result, flag = plan.reader.read(objects)
    except TestError:
        return dict(INVALID)

    inputs = dict(zip(plan.names, values))

    # Transport/leaf/inventory failures already returned; the flag attests to
    # pipe acceptance only, and a mismatch outranks FILTERED.
    if plan.applications:
        accepted = True
        for guard, binding in plan.applications:
            if guard is None:
                continue
            scope = {parameter: inputs[source] for parameter, source in binding}
            if not guard.eval(scope):
                accepted = False
                break
        if flag != (not accepted):
            return dict(INVALID)
        if not accepted:
            return dict(FILTERED)
    elif flag is not None:
        return dict(INVALID)

    predicate = plan.predicate
    if predicate is not None and not predicate.eval(inputs):
        return dict(FILTERED)

    commands: List[str] = []
    cost = 0
    if machine is not None:
        target = machine.index.get(inputs.get(machine.state_param))
        if target is None:
            return dict(UNREACHABLE)
        outcome = plan.preparation.prepare(inputs, target)
        if outcome is None:
            return dict(UNREACHABLE)
        commands = list(outcome[0])
        cost = outcome[1]
        commands.append(inputs[machine.message_param])

    key = identity(run["entry"], keys)
    index = corpus.locate(key)
    if index is None:
        new_inputs = {name: value for name, value in zip(plan.names, values)}
        index = corpus.append(key, run["entry"], new_inputs, cost, commands,
                              position)
        status = "READY"
    else:
        corpus.witness(index, position)
        status = "DUPLICATE"
    return {"status": status, "case": index, "model_result": result}
